{
  "investigation_id": "FISHER_CC9-c363715ca1e83906-pass1",
  "subsystem": "PHYSICAL_IO_WORD_BIT_DECODE",
  "scope": {
    "machine": "FISHER_CC9",
    "project": "FISHER_SCIENTIFIC",
    "interface": "RTA",
    "target_cluster_key": "c363715ca1e83906",
    "word_population": "only rows currently lacking a complete directional hardware-bank match"
  },
  "failure_pattern": "Configio RTA half-words have no complete directional bank-to-module match; numeric suffixes occur in multiple catalog families and are not an authoritative slot or bank key.",
  "affected_count": 95,
  "observed_facts": [
    "Independent aggregate evidence from get_configio_binding_cluster_summary reports 19 no_eipmodules_bank_match words, versus 89 BOUND words.",
    "The no-match set is structurally heterogeneous: 1746-OA16 words 23-25, 1746-IA16 words 1020-1023, 1794-AENT words 276-277 and 2070-2075, and YASKAWA-SI-EN3-ESC words 150-151 and 1150-1151.",
    "At word 23, Configio Low bank 6 with Desc 1746-OA16-16 encounters only a 1746-IA16 input bank; Configio High bank 7 has no match. This is direction- and catalog-incompatible, not evidence for half pairing.",
    "At word 2072, banks 88 and 89 have no module-bank records anywhere in the independently derived hardware bank map, despite numeric suffixes 127 and 128.",
    "The site has valid bound words using the same general descriptor syntax: word 20 is 1746-OA16 suffixes 4/5 with banks 0/1, and word 1000 is 1794-IA16 suffixes 95/96 with banks 68/69. Syntax and terminal number therefore do not supply a universal conversion."
  ],
  "evidence_refs": [
    "get_configio_binding_cluster_summary: 19 no_eipmodules_bank_match words and 89 independently BOUND words",
    "get_eip_bank_map: 106 proven module-bank records across 10 racks",
    "get_configio_word: words 20-25, 1000, 1020-1023, 150-151, 276-277, and 2070-2075",
    "get_configio_binding_trace: word 23 demonstrates direction/catalog conflict plus missing High bank; word 2072 demonstrates both banks absent"
  ],
  "candidate_rule_name": "reject_numeric_suffix_as_cross_rack_binding_key",
  "candidate_rule_description": "Do not infer an adapter, slot, directional bank, or Low/High relationship from the terminal numeric suffix in Configio Desc. Retain the requirement for a complete, direction-compatible hardware-bank match. Where that evidence is absent, retain review status rather than manufacturing a binding.",
  "proposed_inputs": {
    "interface": "RTA",
    "configio_fields": [
      "Bank",
      "LoHi",
      "Desc",
      "In_Out"
    ],
    "hardware_fields": [
      "adapter identity",
      "catalog",
      "direction",
      "input_bank",
      "output_bank",
      "physical_slot",
      "data_index"
    ]
  },
  "proposed_transformation": {
    "operation": "guard_only",
    "steps": [
      "Treat Desc catalog prefix and terminal numeric suffix as descriptive, not as an authoritative rack, slot, or bank key.",
      "Require each usable Configio half to match a hardware bank with compatible direction and catalog evidence where catalog evidence is available.",
      "Require evidence of one coherent word-level relationship; otherwise retain review status.",
      "Never convert a numeric suffix into a rack selector, slot selector, bank conversion, or inferred Low-to-High relationship."
    ]
  },
  "expected_outputs": {
    "on_complete_match": "retain the existing deterministic binding outcome",
    "on_no_complete_match": "review-required without endpoint assignment"
  },
  "supporting_examples": [
    {
      "word": 23,
      "observation": "Low bank 6 is available only as an input bank on T_1747_AENTR_1 slot 5, catalog 1746-IA16, conflicting with Desc 1746-OA16-16; High bank 7 is unmatched."
    },
    {
      "word": 2072,
      "observation": "Neither bank 88 nor 89 exists in the hardware module-bank map although Desc suffixes are 127 and 128."
    },
    {
      "word": 20,
      "observation": "An independently BOUND 1746-OA16 word has suffixes 4/5 and banks 0/1, demonstrating that descriptor syntax does not establish a universal numeric mapping."
    },
    {
      "word": 1000,
      "observation": "An independently BOUND 1794-IA16 word has suffixes 95/96 and banks 68/69, unlike the unbound 1794-AENT ranges."
    }
  ],
  "counterexamples": [
    {
      "candidate": "panel_catalog_numeric_alpha_low_a_slot",
      "reason": "The unresolved population spans 1746, 1794, and YASKAWA descriptor families with no demonstrated common hardware topology; catalog numeric suffix plus Low position is not a proven slot rule."
    },
    {
      "candidate": "infer_high_from_low",
      "reason": "Word 23 has a Low-side bank collision with a direction- and catalog-incompatible input module, while its High bank is absent. It cannot establish a Low/High pairing convention."
    },
    {
      "candidate": "numeric_suffix_to_bank",
      "reason": "Word 2072 uses suffixes 127/128 with banks 88/89, neither of which exists in the complete hardware-bank map."
    }
  ],
  "ambiguities": [
    "No raw convention was found that maps the unresolved Configio numeric suffixes to adapter identity, physical slot, or directional module bank.",
    "The aggregate failure cluster combines heterogeneous descriptor families and both partial and complete half-word bank failures.",
    "YASKAWA descriptor rows have no demonstrated directional-bank correspondence in the available hardware mapping."
  ],
  "additional_evidence_needed": [
    "An authoritative raw cross-reference mapping each affected Configio bank and descriptor to adapter identity and directional module bank.",
    "Raw evidence defining whether unmatched Low or High halves are intentionally absent and, if so, the valid relationship to the other half.",
    "A hardware or source export containing bank records for absent ranges 88-89, 136-139, 216-219, and 266-269, if those banks are expected to be installed."
  ],
  "tests_required": [
    "Apply this guard across all 108 Configio words and verify all 89 independently BOUND words remain unchanged.",
    "Require a compatible directional hardware-bank match for every resolved half before permitting any non-review result.",
    "Reject any attempted binding based only on terminal numeric suffix, half position, adjacent-bank inference, or descriptor text."
  ],
  "confidence": {
    "level": "high",
    "score": 0.93,
    "basis": "Independent aggregate and raw-row evidence strongly rejects numeric-suffix fallback, while no independent evidence supports a positive resolver convention."
  },
  "status": "INSUFFICIENT_EVIDENCE"
}
